messages.content:
Your provider has no native tool calling. tool_choice=auto;parallel_tool_calls=false. You must output exactly one JSON object per turn and no Markdown.
To call a tool, output only an exact name from this turn's list. Shape example; replace values for the current task: {"tool_calls":[{"arguments":"1.1","name":"book.query"}]}
For a final answer, output: {"final":"answer text"}
Select tools only from the following list. arguments must satisfy the corresponding JSON Schema:
[
  {
    "description": "Answer a self-contained semantic question about explicit referents by resolving targets first and then reading source evidence around the frozen bindings.",
    "name": "book.query",
    "parameters": {
      "additionalProperties": false,
      "anyOf": [
        {
          "properties": {
            "intent": {
              "enum": [
                "definition",
                "explanation"
              ]
            }
          }
        },
        {
          "properties": {
            "intent": {
              "enum": [
                "relation",
                "comparison"
              ]
            },
            "targets": {
              "minItems": 2
            }
          }
        }
      ],
      "examples": [
        {
          "anchor_lid": "1.1",
          "intent": "comparison",
          "obligations": [
            {
              "requirement": "State the activation condition at each location."
            },
            {
              "requirement": "Compare whether equality activates each threshold, citing both passages."
            }
          ],
          "query": "How do the activation conditions of the alpha threshold and beta threshold differ?",
          "targets": [
            "alpha threshold",
            "beta threshold"
          ]
        }
      ],
      "properties": {
        "anchor_lid": {
          "description": "Required known LID in this book anchoring referent resolution. It provides local context without restricting evidence retrieval to this node.",
          "type": "string"
        },
        "intent": {
          "description": "Question kind: definition or explanation requires 1..3 targets; relation or comparison requires 2..3 separately named targets.",
          "enum": [
            "definition",
            "explanation",
            "relation",
            "comparison"
          ],
          "type": "string"
        },
        "obligations": {
          "description": "One to three answer requirements, each in its own requirement object; these guide evidence sufficiency for the requested answer.",
          "items": {
            "additionalProperties": false,
            "properties": {
              "requirement": {
                "description": "One nonblank, independently checkable requirement the semantic answer must address.",
                "type": "string"
              }
            },
            "required": [
              "requirement"
            ],
            "type": "object"
          },
          "maxItems": 3,
          "minItems": 1,
          "type": "array"
        },
        "query": {
          "description": "Self-contained, nonblank semantic question about the named targets, with enough context to resolve referents. Use literal search for exact wording or first/previous occurrences.",
          "type": "string"
        },
        "targets": {
          "description": "Explicit referents to resolve before reading evidence. Each item is nonblank and unique after trimming and lowercasing; name comparison/relation targets separately, not as one combined phrase.",
          "items": {
            "type": "string"
          },
          "maxItems": 3,
          "minItems": 1,
          "type": "array"
        }
      },
      "required": [
        "anchor_lid",
        "intent",
        "obligations",
        "query",
        "targets"
      ],
      "type": "object"
    }
  },
  {
    "description": "Synthesize a caller-supplied discrete LID set without expanding retrieval, returning an answer whose citations are a subset of the input LIDs.",
    "name": "book.synthesize",
    "parameters": {
      "additionalProperties": false,
      "examples": [
        {
          "lids": [
            "1.1",
            "1.2"
          ],
          "task": "Summarize these two threshold conditions using only these passages; state any evidence gaps."
        }
      ],
      "properties": {
        "lids": {
          "description": "Nonempty list of known LIDs selected as the complete evidence scope. Synthesis reads only these nodes and returns citations drawn from this list, without expanding retrieval.",
          "items": {
            "type": "string"
          },
          "minItems": 1,
          "type": "array"
        },
        "task": {
          "description": "Synthesis instruction for the supplied LIDs; omit or null to synthesize their content without an additional task.",
          "type": [
            "string",
            "null"
          ]
        }
      },
      "required": [
        "lids"
      ],
      "type": "object"
    }
  },
  {
    "description": "Enumerate the complete set of literal-text occurrences in canonical source, returning stable source UTF-16 ranges, the total count, and a pagination cursor.",
    "name": "book.search_text",
    "parameters": {
      "additionalProperties": false,
      "examples": [
        {
          "match_mode": "exact",
          "order": "document",
          "page_size": 1,
          "query": "threshold"
        },
        {
          "match_mode": "normalized",
          "order": "reverse_document",
          "page_size": 1,
          "query": "THRESHOLD",
          "scope": {
            "relative_to": {
              "direction": "before",
              "lid": "1.3"
            },
            "within_lid": "1"
          }
        }
      ],
      "properties": {
        "cursor": {
          "description": "Opaque next_cursor from the preceding search result. Omit or null for the first page; preserve query, match_mode, scope, order and page_size on continuation. A changed source revision invalidates it.",
          "type": [
            "string",
            "null"
          ]
        },
        "match_mode": {
          "default": "exact",
          "description": "exact (default) matches unchanged text; normalized applies NFKC, full non-Turkic case folding and whitespace collapsing. Both locate literal occurrences, not semantic equivalents; result ranges use original-source UTF-16 positions.",
          "enum": [
            "exact",
            "normalized"
          ],
          "type": "string"
        },
        "order": {
          "default": "document",
          "description": "document (default) returns earliest occurrences first; reverse_document returns latest first. Uses canonical source order, not lexical LID sorting. Combine before with reverse_document for previous occurrences.",
          "enum": [
            "document",
            "reverse_document"
          ],
          "type": "string"
        },
        "page_size": {
          "default": 20,
          "description": "Maximum literal occurrences per search page, 1..50, default 20. Does not change total_occurrences or exhaustive coverage of the requested literal scope; preserve it when using cursor.",
          "format": "uint",
          "maximum": 50.0,
          "minimum": 1.0,
          "type": "integer"
        },
        "query": {
          "description": "Literal text to locate in canonical source, containing non-whitespace text and at most 4,096 Unicode scalar values. Exact mode preserves query whitespace; this is not a semantic question or regex. Read chosen hits using their start_lid/end_lid.",
          "maxLength": 4096,
          "minLength": 1,
          "type": "string"
        },
        "scope": {
          "anyOf": [
            {
              "additionalProperties": false,
              "properties": {
                "relative_to": {
                  "anyOf": [
                    {
                      "additionalProperties": false,
                      "properties": {
                        "direction": {
                          "description": "before keeps hits ending at or before the reference span's start; after keeps hits starting at or after its end. Direction filters scope independently of result order.",
                          "enum": [
                            "before",
                            "after"
                          ],
                          "type": "string"
                        },
                        "lid": {
                          "description": "Known reference LID in this book. The relative filter excludes this node's entire source span, including its descendants.",
                          "type": "string"
                        }
                      },
                      "required": [
                        "direction",
                        "lid"
                      ],
                      "type": "object"
                    },
                    {
                      "type": "null"
                    }
                  ],
                  "description": "Optional before/after filter around a known LID, excluding that node's span. Intersects with within_lid when both are supplied."
                },
                "within_lid": {
                  "description": "Known LID whose source span, including descendants, must contain each whole hit. Omit or null for no subtree restriction.",
                  "type": [
                    "string",
                    "null"
                  ]
                }
              },
              "type": "object"
            },
            {
              "type": "null"
            }
          ],
          "description": "Optional source scope using known LIDs from this book. Omit, null or {} searches the whole book; within_lid and relative_to intersect, and each whole hit must fit the resulting range."
        }
      },
      "required": [
        "query"
      ],
      "type": "object"
    }
  },
  {
    "description": "Read canonical source text by one LID or an inclusive LID range.",
    "name": "book.text",
    "parameters": {
      "additionalProperties": false,
      "examples": [
        {
          "end_lid": "1.2",
          "lid": "1.1"
        }
      ],
      "properties": {
        "end_lid": {
          "description": "Inclusive final LID in source reading order; for a search hit, use end_lid. Reads from lid's span start through end_lid's span end. Omit or null to read only lid's span.",
          "type": [
            "string",
            "null"
          ]
        },
        "lid": {
          "description": "Known LID from this book's locating or structure results; for a search hit, use start_lid. Reads the node's canonical source span, including descendants.",
          "type": "string"
        }
      },
      "required": [
        "lid"
      ],
      "type": "object"
    }
  },
  {
    "description": "Find Resident tools by required capabilities, scope, operation, and authorized effect mode. Natural-language task text ranks only candidates that pass Runtime gates; matches never execute a target tool, and newly activated deferred tools become visible in the next sampling.",
    "name": "tool.search",
    "parameters": {
      "additionalProperties": false,
      "description": "Matches include use_when/avoid_when. Unmet capabilities have capability-level reasons. Optional next_searches entries are complete arguments for tool.search; choose one only if useful. Discovery and recovery suggestions do not execute matched tools or grant permissions.",
      "examples": [
        {
          "effect_mode": "read_only",
          "max_results": 2,
          "operation": "summarize",
          "required_capabilities": [
            "structural_index"
          ],
          "scope": "document",
          "task": "Outline the main argument of this book without moving the Reader"
        },
        {
          "effect_mode": "read_only",
          "max_results": 1,
          "operation": "locate_literal",
          "required_capabilities": [
            "lexical_locate"
          ],
          "scope": "document",
          "task": "Find the first literal occurrence of equal time"
        },
        {
          "effect_mode": "read_only",
          "max_results": 1,
          "operation": "read_source",
          "required_capabilities": [
            "source_read"
          ],
          "scope": "passage",
          "task": "Read the passage selected from the search results"
        },
        {
          "effect_mode": "reader_mutation_explicitly_requested",
          "max_results": 2,
          "operation": "mutate_reader",
          "required_capabilities": [
            "reader_write"
          ],
          "scope": "passage",
          "task": "Save the user's requested note on the current passage"
        }
      ],
      "properties": {
        "effect_mode": {
          "enum": [
            "read_only",
            "reader_mutation_explicitly_requested"
          ],
          "type": "string"
        },
        "max_results": {
          "maximum": 6,
          "minimum": 1,
          "type": "integer"
        },
        "operation": {
          "enum": [
            "locate_literal",
            "read_source",
            "explain",
            "compare",
            "summarize",
            "navigate",
            "mutate_reader"
          ],
          "type": "string"
        },
        "required_capabilities": {
          "items": {
            "enum": [
              "discovery",
              "source_read",
              "lexical_locate",
              "semantic_evidence",
              "structural_index",
              "synthesis",
              "navigation_plan",
              "artifact_read",
              "source_presentation",
              "presentation_authoring",
              "profile_read",
              "profile_trace",
              "memory_read",
              "memory_write",
              "reader_read",
              "reader_write",
              "goal_management"
            ],
            "type": "string"
          },
          "maxItems": 17,
          "minItems": 1,
          "type": "array",
          "uniqueItems": true
        },
        "scope": {
          "enum": [
            "selection",
            "passage",
            "section",
            "document",
            "corpus"
          ],
          "type": "string"
        },
        "task": {
          "description": "Natural-language task used only to rank already-authorized candidates",
          "maxLength": 512,
          "minLength": 1,
          "type": "string"
        }
      },
      "required": [
        "task",
        "required_capabilities",
        "scope",
        "operation",
        "effect_mode",
        "max_results"
      ],
      "type": "object"
    }
  },
  {
    "description": "Return context pointers for a LID: near adds tree adjacency and local edges, mid adds other concept or entity occurrences, and far adds long-range edges. Pointers contain no source text; use book.text to read it.",
    "name": "book.context",
    "parameters": {
      "additionalProperties": false,
      "examples": [
        {
          "granularity": "near",
          "k": 3,
          "lid": "1.2"
        }
      ],
      "properties": {
        "granularity": {
          "anyOf": [
            {
              "enum": [
                "near",
                "mid",
                "far"
              ],
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "default": "near",
          "description": "Context reach: near includes tree adjacency and local relations; mid adds other concept/entity occurrences; far also adds long-range relations. Omit or null for near."
        },
        "k": {
          "default": 10,
          "description": "Maximum number of context pointers returned across all layers. Omit or null for 10; zero returns no items. Counts pointers, not characters or source passages.",
          "format": "uint",
          "minimum": 0.0,
          "type": [
            "integer",
            "null"
          ]
        },
        "lid": {
          "description": "Known LID in this book to expand around. Returned items are context pointers; read their LIDs through the source-text tool for evidence.",
          "type": "string"
        }
      },
      "required": [
        "lid"
      ],
      "type": "object"
    }
  },
  {
    "description": "Deterministically recall whole-book concept and entity candidates with match reasons, bounded previews, and complete occurrence LIDs. After choosing candidates, read their full evidence with book.text.",
    "name": "book.concept",
    "parameters": {
      "additionalProperties": false,
      "examples": [
        {
          "anchor_lid": "1.2",
          "limit": 5,
          "query": "threshold"
        }
      ],
      "properties": {
        "anchor_lid": {
          "description": "Optional known LID in this book to rank nearby candidates and previews. Omit or null for unanchored ranking; this does not restrict recall to a subtree.",
          "type": [
            "string",
            "null"
          ]
        },
        "limit": {
          "default": 12,
          "description": "Maximum concept/entity candidates, 1..50; omit or null for 12. Inspect matched_count and truncated for candidate coverage; this does not limit occurrences within a candidate.",
          "format": "uint",
          "maximum": 50,
          "minimum": 1,
          "type": [
            "integer",
            "null"
          ]
        },
        "query": {
          "description": "Nonblank concept/entity name, alias or descriptive terms for deterministic candidate recall from names and occurrence text. At most 4,096 Unicode scalar values, including surrounding whitespace; not literal occurrence enumeration.",
          "maxLength": 4096,
          "minLength": 1,
          "type": "string"
        }
      },
      "required": [
        "query"
      ],
      "type": "object"
    }
  },
  {
    "description": "Project BookStructure to explain a LID's role in the whole-book spine, throughline, and key stops. Without at, return the whole-book overview; when the sidecar is absent, return explicit unavailable status.",
    "name": "book.structure",
    "parameters": {
      "additionalProperties": false,
      "examples": [
        {
          "at": "1.2"
        }
      ],
      "properties": {
        "at": {
          "description": "Optional known LID in this book to locate its structural role or current route segment. Omit or null for the whole-book view; this is a location, not a natural-language query.",
          "type": [
            "string",
            "null"
          ]
        }
      },
      "type": "object"
    }
  },
  {
    "description": "Save highlight or position memory; qa records the user's original question after answering with book.query; context records sourced reader background, preferences, interests or sticking points. Use reader.note for every note: note is not a memory.save type. anchor_lid is the question or memory location. context may cite real LIDs supporting it.",
    "name": "memory.save",
    "parameters": {
      "properties": {
        "anchor_lid": {
          "type": "string"
        },
        "citations": {
          "description": "Optional real LIDs supporting this memory, primarily for context; invalid LIDs are dropped and the list may be empty",
          "items": {
            "type": "string"
          },
          "type": "array"
        },
        "content": {
          "type": "string"
        },
        "type": {
          "enum": [
            "highlight",
            "position",
            "qa",
            "context"
          ],
          "type": "string"
        }
      },
      "required": [
        "type",
        "anchor_lid",
        "content"
      ],
      "type": "object"
    }
  },
  {
    "description": "Attach a note to a LID through a thin entry point whose persistence is delegated to memory. Returns note_id, which is the memory-layer ID.",
    "name": "reader.note",
    "parameters": {
      "properties": {
        "lid": {
          "type": "string"
        },
        "text": {
          "description": "Note content",
          "type": "string"
        }
      },
      "required": [
        "lid",
        "text"
      ],
      "type": "object"
    }
  },
  {
    "description": "Return current Reader session state {viewport, open_panels, selection, layout, profile, paper_minimap, paper_minimap_agent_context} for mid-session entry or resynchronization after manual actions.",
    "name": "reader.state",
    "parameters": {
      "properties": {},
      "type": "object"
    }
  }
]
